<script lang="ts">import '$lib/design/tokens.css'; import '$lib/components/commerce/store.css'; import { comparable } from '$lib/smart-shopping'; import type { PageData } from './$types'; let { data }: { data: PageData } = $props(); let ids = $state<number[]>([]); $effect(() => { ids = data.ids; }); let selected = $derived((data.products as any[]).filter((p) => ids.includes(p.id))); const labels: Record<string,string> = { machine_type:'نوع دستگاه', stroke_mm:'استروک (mm)', voltage_min:'حداقل ولتاژ (V)', voltage_max:'حداکثر ولتاژ (V)', needle_configuration:'آرایش سوزن', needle_count:'تعداد سوزن', diameter_mm:'قطر سوزن (mm)', ink_type:'نوع رنگ', color_family:'خانواده رنگ' }; function toggle(id:number) { ids = ids.includes(id) ? ids.filter(x=>x!==id) : ids.length < 3 ? [...ids,id] : ids; } function share() { const url = new URL(window.location.href); ids.length ? url.searchParams.set('products', ids.join(',')) : url.searchParams.delete('products'); history.replaceState({}, '', url); }</script>
<svelte:head><title>مقایسهٔ محصولات | اینکورا</title></svelte:head><div class="inkora-theme inkora-store smart-page" dir="rtl"><header class="store-header"><div class="store-container store-header-inner"><a class="store-brand" href="/"><img src="/assets/brand/inkora-wordmark-temporary.svg" alt="اینکورا؛ نوشتار موقت برند" /></a><nav class="store-nav" aria-label="ناوبری"><a href="/advisor">انتخاب‌گر</a><a href="/compare" aria-current="page">مقایسه</a><a href="/simulator">شبیه‌ساز</a></nav></div></header><main class="store-container store-main"><p class="eyebrow">فقط دادهٔ هم‌گروه</p><h1>مقایسهٔ محصولات واقعی</h1>{#if data.status === 'error'}<p role="alert">دادهٔ فروشگاه در دسترس نیست.</p>{:else if !data.products.length}<section class="smart-panel"><h2>کالای قابل مقایسه نداریم</h2><p>مدیر باید برای دو یا سه کالای واقعی، منتشرشده و موجود از یک گروه، متادیتای Inkora را ثبت کند.</p></section>{:else}<section class="smart-panel"><h2>تا سه کالا انتخاب کنید</h2><div class="compare-choices">{#each data.products as product}<label><input type="checkbox" checked={ids.includes(product.id)} onchange={() => toggle(product.id)} /> {product.name} <small>({product.inkora_smart.group})</small></label>{/each}</div><button class="button" onclick={share} disabled={!ids.length}>به‌روزرسانی پیوند قابل اشتراک</button></section>{#if ids.length && !comparable(selected.map(p => ({id:p.id,name:p.name,slug:p.slug,smart:p.inkora_smart})))}<p class="empty-copy" role="alert">فقط ۲ یا ۳ محصول از یک گروه قابل مقایسه‌اند.</p>{:else if comparable(selected.map(p => ({id:p.id,name:p.name,slug:p.slug,smart:p.inkora_smart})))}<div class="compare-table-wrap"><table><caption>مقایسهٔ داده‌های ثبت‌شده؛ خانهٔ خالی یعنی داده‌ای وارد نشده است.</caption><thead><tr><th>مشخصه</th>{#each selected as p}<th><a href={`/shop/${p.slug}`}>{p.name}</a></th>{/each}</tr></thead><tbody><tr><th>سطح مهارت</th>{#each selected as p}<td>{p.inkora_smart.skill_level || 'ثبت نشده'}</td>{/each}</tr><tr><th>سبک‌های پشتیبانی‌شده</th>{#each selected as p}<td>{p.inkora_smart.supported_styles?.join('، ') || 'ثبت نشده'}</td>{/each}</tr>{#each Object.keys(labels) as key}<tr><th>{labels[key]}</th>{#each selected as p}<td>{p.inkora_smart.specifications?.[key] ?? 'ثبت نشده'}</td>{/each}</tr>{/each}</tbody></table></div>{/if}{/if}</main></div>
